// Extract & normalize - never trust raw input
const body = $input.first().json.body || $input.first().json;
const ipRegex = /^(?:\d{1,3}\.){3}\d{1,3}$/;
const sourceIp = ipRegex.test(body.source_ip || '') ? body.source_ip : null;
return [{ json: {
  alert: {
    timestamp: body.timestamp || new Date().toISOString(),
    alert_type: String(body.alert_type || 'unknown').slice(0, 80),
    severity_raw: body.severity || 'low',
    source_ip: sourceIp,
    host: body.host || 'unknown',
    instance_id: body.instance_id || '',
    event: body.event || {},
    mitre: body.mitre || {}
  },
  needs_vt: !!sourceIp && sourceIp !== 'localhost' && sourceIp !== '127.0.0.1'
}}];

const alertNode = $('2. Extract IP & Event').first().json;
let vt = { skipped: true, malicious: 0, suspicious: 0, country: null, as_owner: null, reputation: null };
try {
  const attrs = $input.first().json.data.attributes;
  vt = { skipped: false, malicious: attrs.last_analysis_stats.malicious, suspicious: attrs.last_analysis_stats.suspicious, harmless: attrs.last_analysis_stats.harmless, country: attrs.country, as_owner: attrs.as_owner, reputation: attrs.reputation };
} catch(e) {}
return [{ json: { alert: alertNode.alert, virustotal: vt } }];

const prev = $('4. Enrich Context').first().json;
let analysis;
try { analysis = JSON.parse($input.first().json.choices[0].message.content); }
catch(e) { analysis = { summary: 'LLM parse failed - escalate', severity: 'high', confidence: 0, is_true_positive: true, recommended_action: 'escalate_human', next_steps: ['Manual review'] }; }
const shouldIsolate = analysis.is_true_positive && analysis.confidence >= 70 && (analysis.severity === 'critical' || (analysis.severity === 'high' && analysis.recommended_action === 'isolate_instance'));
return [{ json: { alert: prev.alert, virustotal: prev.virustotal, analysis, should_isolate: shouldIsolate } }];
